package com.zhixing.controller;
import com.zhixing.dto.TaskEventRequest; import com.zhixing.model.AuthenticatedSession; import com.zhixing.model.DailyPackageView; import com.zhixing.model.DailyTaskView; import com.zhixing.service.DailyTaskService; import com.zhixing.service.SessionService; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import javax.validation.Valid; import java.time.LocalDate;
/** F04 今日任务：用户只能读取和变更自己的任务，客户端从不提交完成率。 */
@RestController public class DailyTaskController { private final SessionService sessions; private final DailyTaskService daily; public DailyTaskController(SessionService sessions,DailyTaskService daily){this.sessions=sessions;this.daily=daily;} @GetMapping("/api/days/{date}") public DailyPackageView day(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return daily.get(user(auth),date);} @PostMapping("/api/days/{date}/activate") public DailyPackageView activate(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return daily.activate(user(auth),date,true);} @PostMapping("/api/tasks/{id}/events") public DailyTaskView event(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable("id") String id,@Valid @RequestBody TaskEventRequest request){return daily.event(user(auth),id,request);} private String user(String auth){AuthenticatedSession session=sessions.requireUser(auth);return session.getUserId();} }
